<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

class MMC_Finance_Admin {
    public function __construct() {
        add_action('admin_menu',array($this,'menu'));
        add_action('admin_post_mmc_fin_add_entry',array($this,'add_entry'));
        add_action('admin_post_mmc_fin_update_entry',array($this,'update_entry'));
        add_action('admin_post_mmc_fin_sync_invoices',array($this,'sync_invoices'));
        add_action('admin_post_mmc_fin_update_invoice',array($this,'update_invoice'));
        add_action('admin_post_mmc_fin_generate_refund',array($this,'generate_refund'));
        add_action('admin_post_mmc_fin_update_refund',array($this,'update_refund'));
        add_action('admin_post_mmc_fin_save_close_inputs',array($this,'save_close_inputs'));
        add_action('admin_post_mmc_fin_request_close',array($this,'request_close'));
        add_action('admin_post_mmc_fin_sync_all',array($this,'sync_all'));
    }

    public function menu(){ add_submenu_page('mmc-dashboard','Finans & Kapanış','Finans & Kapanış','mmc_manage_finance','mmc-finance',array($this,'page')); }
    private function guard(){if(!current_user_can('mmc_manage_finance'))wp_die('Bu alan için yetkiniz yok.');}

    public function page(){
        $this->guard(); $programs=MMC_Program_Service::all_programs(); $pid=absint($_GET['program_id']??0); if(!$pid&&$programs)$pid=(int)$programs[0]->id;
        $program=$pid?MMC_Program_Service::get_program($pid):null;
        if($program){MMC_Finance_Service::sync_external_sources($pid);MMC_Finance_Service::ensure_deposit_refunds($pid);}
        $summary=$program?MMC_Finance_Service::summary($pid):null; $entries=$program?MMC_Finance_Service::entries($pid):array(); $invoices=$program?MMC_Finance_Service::invoices($pid):array(); $refunds=$program?MMC_Finance_Service::deposit_refunds($pid):array(); $readiness=$program?MMC_Finance_Service::readiness($pid):null;
        $event=$program&&class_exists('MMC_Event_Service')?MMC_Event_Service::event_for_program($pid):null;
        $coverage=$event&&class_exists('MMC_Sales_Service')?MMC_Sales_Service::mapping_coverage($event->id):null;
        ?>
        <div class="wrap mmc-wrap"><h1>Finans & Teminat Kapanış Modülü</h1><p class="mmc-lead">Programın gerçek gelir, gider, fatura ve teminat akışını tek finans defterinde toplar. Teminat gider sayılmaz; yalnız kesilen kısmı gider olur.</p><?php $this->notice(); ?>
        <div class="mmc-panel"><form method="get" class="mmc-inline-form"><input type="hidden" name="page" value="mmc-finance"><label>Program<select name="program_id" onchange="this.form.submit()"><option value="">Seçin</option><?php foreach($programs as $p):?><option value="<?php echo esc_attr($p->id);?>" <?php selected($pid,$p->id);?>><?php echo esc_html($p->program_code.' — '.$p->province_name.' / '.($p->district_name?:'Genel'));?></option><?php endforeach;?></select></label></form></div>
        <?php if(!$program):?><div class="notice notice-info"><p>Program seçin.</p></div></div><?php return;endif;?>
        <?php if($coverage && !$coverage['complete']):?><div class="notice notice-warning inline"><p><strong>Satış eşleştirmesi eksik (<?php echo esc_html($coverage['mapped'].'/'.$coverage['required']);?>).</strong> Aşağıdaki sıfır gelir/sipariş rakamları satış yapılmadığını kanıtlamaz; henüz eşleşmeyen WooCommerce siparişleri finans defterine gelmez. <a href="<?php echo esc_url(admin_url('admin.php?page=mmc-sales&program_id='.$pid));?>">Satış eşleştirmesine git</a>.</p></div><?php endif;?>

        <div class="mmc-panel mmc-hero-panel"><div><small><?php echo esc_html($program->program_code);?></small><h2><?php echo esc_html($program->province_name.' / '.($program->district_name?:'Genel'));?></h2></div><div><strong>Aşama:</strong> <?php echo esc_html(MMC_Program_Service::statuses()[$program->status]??$program->status);?></div></div>
        <div class="mmc-cards mmc-cards-5">
            <div class="mmc-card"><span>Toplam Gelir</span><strong><?php echo $this->money($summary['total_revenue']);?></strong><small>Web + diğer gerçekleşen gelir</small></div>
            <div class="mmc-card"><span>Gerçek Gider</span><strong><?php echo $this->money($summary['actual_expense']);?></strong><small>Teminat hariç</small></div>
            <div class="mmc-card"><span>Net Kâr / Zarar</span><strong><?php echo $this->money($summary['net_profit']);?></strong><small>%<?php echo esc_html(number_format_i18n($summary['profit_margin'],1));?> marj</small></div>
            <div class="mmc-card"><span>İade Bekleyen Teminat</span><strong><?php echo $this->money($summary['deposit_outstanding']);?></strong><small><?php echo esc_html($summary['unresolved_deposits']);?> açık kayıt</small></div>
            <div class="mmc-card"><span>Fatura Bekleyen</span><strong><?php echo esc_html($summary['pending_invoices']);?></strong><small>Sipariş / kayıt</small></div>
        </div>

        <div class="mmc-panel"><h2>1. Otomatik Satış Özeti</h2><p>WooCommerce / PayTR satış defterinden gelir; bu rakamı ayrıca manuel gelir olarak girmeyin.</p><table class="widefat striped"><tbody>
            <tr><th>Sipariş</th><td><?php echo esc_html(number_format_i18n((int)($summary['sales']['orders_count']??0)));?></td><th>Satılan Bilet</th><td><?php echo esc_html(number_format_i18n((int)($summary['sales']['tickets']??0)));?></td></tr>
            <tr><th>Web Seyirci/Kapasite</th><td><?php echo esc_html(number_format_i18n($summary['web_audience']));?></td><th>Brüt Satış</th><td><?php echo $this->money((float)($summary['sales']['gross_revenue']??0));?></td></tr>
            <tr><th>İade</th><td><?php echo $this->money((float)($summary['sales']['refunds']??$summary['sales']['refunded_amount']??0));?></td><th>Net Web Geliri</th><td><strong><?php echo $this->money((float)($summary['sales']['web_revenue']??$summary['sales']['net_revenue']??0));?></strong></td></tr>
        </tbody></table><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" style="margin-top:12px"><input type="hidden" name="action" value="mmc_fin_sync_all"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><?php wp_nonce_field('mmc_fin_sync_'.$pid);?><button class="button">Finans Kaynaklarını Şimdi Yenile</button></form></div>

        <div class="mmc-grid-2">
            <div class="mmc-panel"><h2>2. Gelir / Gider Ekle</h2><p>Gişe, Biletinial, sponsor, personel, güvenlik, komisyon gibi web sistemi dışında kalan kalemler içindir.</p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmc_fin_add_entry"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><?php wp_nonce_field('mmc_fin_add_'.$pid);?><div class="mmc-form-grid">
                <label>Tür<select name="entry_class" id="mmc-fin-class"><option value="income">Gelir</option><option value="expense">Gider</option></select></label>
                <label>Kategori<select name="category"><?php foreach(MMC_Finance_Service::categories('income') as $k=>$v):?><option value="<?php echo esc_attr($k);?>"><?php echo esc_html('Gelir — '.$v);?></option><?php endforeach;?><?php foreach(MMC_Finance_Service::categories('expense') as $k=>$v):?><option value="<?php echo esc_attr($k);?>"><?php echo esc_html('Gider — '.$v);?></option><?php endforeach;?></select></label>
                <label>Başlık<input name="title" required></label><label>Tutar<input type="number" min="0" step="0.01" name="amount" required></label>
                <label>Durum<select name="status"><option value="planned">Planlandı</option><option value="pending">Bekliyor</option><option value="realized">Gerçekleşti / Tahsil</option><option value="paid">Ödendi / Tahsil</option><option value="incurred">Gerçekleşti (gider)</option></select></label><label>Vade<input type="date" name="due_date"></label>
                <label>Referans / Dekont<input name="reference_no"></label><label class="mmc-span-2">Not<textarea name="notes"></textarea></label>
                </div><?php submit_button('Gelir / Gider Kaydını Ekle','primary');?></form></div>
            <div class="mmc-panel"><h2>3. Seyirci Kapanış Bilgisi</h2><p>Web satış seyircisi otomatik gelir. Buraya yalnız gişe/Biletinial vb. web dışı ücretli seyirci ve ücretsiz/davetliyi yazın.</p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmc_fin_save_close_inputs"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><?php wp_nonce_field('mmc_fin_close_inputs_'.$pid);?><div class="mmc-form-grid"><label>Web dışı ücretli seyirci<input type="number" min="0" name="manual_paid_audience" value="<?php echo esc_attr($summary['manual_paid_audience']);?>"></label><label>Davetli / ücretsiz<input type="number" min="0" name="free_audience" value="<?php echo esc_attr($summary['free_audience']);?>"></label><label class="mmc-span-2">Kapanış notu<textarea name="notes"><?php echo esc_textarea($summary['closure']->notes??'');?></textarea></label></div><?php submit_button('Seyirci / Kapanış Bilgisini Kaydet','secondary');?></form><hr><p><strong>Toplam gerçek seyirci:</strong> <?php echo esc_html(number_format_i18n($summary['total_audience']));?></p><p><strong>Kişi başı gelir:</strong> <?php echo $this->money($summary['revenue_per_person']);?> &nbsp; <strong>Kişi başı gider:</strong> <?php echo $this->money($summary['expense_per_person']);?></p></div>
        </div>

        <div class="mmc-panel"><h2>4. Finans Defteri</h2><div class="mmc-table-scroll"><table class="widefat striped"><thead><tr><th>Tür</th><th>Kategori / Açıklama</th><th>Tutar</th><th>Durum</th><th>Vade / Tarih</th><th>Referans</th><th>Güncelle</th></tr></thead><tbody><?php if(!$entries):?><tr><td colspan="7">Finans kaydı yok.</td></tr><?php else:foreach($entries as $e):?><tr><td><?php echo esc_html(MMC_Finance_Service::entry_classes()[$e->entry_class]??$e->entry_class);?></td><td><strong><?php echo esc_html(MMC_Finance_Service::categories($e->entry_class)[$e->category]??$e->category);?></strong><br><small><?php echo esc_html($e->title);?></small></td><td><?php echo $this->money($e->amount);?></td><td><?php echo esc_html(MMC_Finance_Service::entry_statuses()[$e->status]??$e->status);?></td><td><?php echo esc_html($e->due_date?:($e->paid_at?:'—'));?></td><td><?php echo esc_html($e->reference_no?:'—');?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" class="mmc-inline-form"><input type="hidden" name="action" value="mmc_fin_update_entry"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><input type="hidden" name="entry_id" value="<?php echo esc_attr($e->id);?>"><?php wp_nonce_field('mmc_fin_entry_'.$pid.'_'.$e->id);?><input type="number" step="0.01" min="0" name="amount" value="<?php echo esc_attr($e->amount);?>" style="width:100px"><select name="status"><?php foreach(MMC_Finance_Service::entry_statuses() as $k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($e->status,$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select><input name="reference_no" value="<?php echo esc_attr($e->reference_no);?>" placeholder="Dekont/ref." style="width:110px"><button class="button button-small">Kaydet</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div>

        <div class="mmc-panel"><h2>5. Fatura Kuyruğu</h2><p>Başarılı WooCommerce siparişlerinden Mikro e-Portal için takip kuyruğu oluşturur. Bu sürüm Mikro’ya otomatik fatura kesmez; kesilen faturayı burada işaretlersiniz.</p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmc_fin_sync_invoices"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><?php wp_nonce_field('mmc_fin_invoices_'.$pid);?><button class="button button-primary">WooCommerce Siparişlerinden Fatura Kuyruğunu Yenile</button></form><div class="mmc-table-scroll" style="margin-top:12px"><table class="widefat striped"><thead><tr><th>Sipariş</th><th>Müşteri</th><th>Tutar</th><th>Durum</th><th>Fatura No / Tarih</th><th>İşlem</th></tr></thead><tbody><?php if(!$invoices):?><tr><td colspan="6">Henüz fatura kuyruğu oluşturulmadı.</td></tr><?php else:foreach($invoices as $i):?><tr><td><?php echo esc_html('woo_order'===$i->source_type?'#'.$i->source_id:$i->source_type);?></td><td><?php echo esc_html($i->customer_name?:'—');?><br><small><?php echo esc_html($i->customer_email?:'');?></small></td><td><?php echo $this->money($i->amount);?></td><td><?php echo esc_html(MMC_Finance_Service::invoice_statuses()[$i->status]??$i->status);?></td><td><?php echo esc_html(($i->invoice_no?:'—').' / '.($i->invoice_date?:'—'));?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmc_fin_update_invoice"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><input type="hidden" name="invoice_id" value="<?php echo esc_attr($i->id);?>"><?php wp_nonce_field('mmc_fin_invoice_'.$pid.'_'.$i->id);?><select name="status"><?php foreach(MMC_Finance_Service::invoice_statuses() as $k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($i->status,$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select><input name="invoice_no" value="<?php echo esc_attr($i->invoice_no);?>" placeholder="Fatura no"><input type="date" name="invoice_date" value="<?php echo esc_attr($i->invoice_date);?>"><input type="url" name="external_url" value="<?php echo esc_attr($i->external_url);?>" placeholder="Drive/Mikro link"><button class="button">Kaydet</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div>

        <div class="mmc-panel"><h2>6. Salon Teminat İadesi</h2><p>Teminat, ödeme anında gider değildir. İade eksik gelirse yalnız kesinti tutarı otomatik gider yazılır.</p><?php if(!$refunds):?><p>Ödenmiş salon teminatı bulunmuyor.</p><?php else:foreach($refunds as $r):$doc=$r->request_document_id?MMC_Finance_Service::get_document($r->request_document_id):null;?><div class="mmc-panel" style="background:#fff"><h3><?php echo esc_html(($r->venue_name?:'Salon').' — '.$this->money($r->deposit_amount));?></h3><p><strong>Durum:</strong> <?php echo esc_html(MMC_Finance_Service::refund_statuses()[$r->status]??$r->status);?> · <strong>İade:</strong> <?php echo $this->money($r->refunded_amount);?> · <strong>Kesinti:</strong> <?php echo $this->money($r->deduction_amount);?></p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" style="display:inline-block"><input type="hidden" name="action" value="mmc_fin_generate_refund"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><input type="hidden" name="refund_id" value="<?php echo esc_attr($r->id);?>"><?php wp_nonce_field('mmc_fin_refund_letter_'.$pid.'_'.$r->id);?><button class="button">Teminat İade Dilekçesini Hazırla / Yenile</button></form><?php if($doc):?><details style="margin:12px 0"><summary><strong>Dilekçe Taslağını Göster</strong></summary><pre style="white-space:pre-wrap;background:#f6f7f7;padding:12px"><?php echo esc_html($doc->content);?></pre></details><?php endif;?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmc_fin_update_refund"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><input type="hidden" name="refund_id" value="<?php echo esc_attr($r->id);?>"><?php wp_nonce_field('mmc_fin_refund_'.$pid.'_'.$r->id);?><div class="mmc-form-grid"><label>Durum<select name="status"><?php foreach(MMC_Finance_Service::refund_statuses() as $k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($r->status,$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select></label><label>Dilekçe tarihi<input type="date" name="request_date" value="<?php echo esc_attr($r->request_date);?>"></label><label>Giden evrak no<input name="outgoing_reference" value="<?php echo esc_attr($r->outgoing_reference);?>"></label><label>İade/dekont ref.<input name="refund_reference" value="<?php echo esc_attr($r->refund_reference);?>"></label><label>İade edilen tutar<input type="number" step="0.01" min="0" name="refunded_amount" value="<?php echo esc_attr($r->refunded_amount);?>"></label><label>Kesinti tutarı<input type="number" step="0.01" min="0" name="deduction_amount" value="<?php echo esc_attr($r->deduction_amount);?>"></label><label class="mmc-span-2">Kesinti nedeni<textarea name="deduction_reason"><?php echo esc_textarea($r->deduction_reason);?></textarea></label><label class="mmc-span-2">Not<textarea name="notes"><?php echo esc_textarea($r->notes);?></textarea></label></div><?php submit_button('Teminat Takibini Güncelle','secondary');?></form></div><?php endforeach;endif;?></div>

        <div class="mmc-panel"><h2>7. Nihai Kârlılık & Program Kapanışı</h2><table class="widefat striped"><tbody><tr><th>Toplam Gelir</th><td><?php echo $this->money($summary['total_revenue']);?></td><th>Toplam Gerçek Gider</th><td><?php echo $this->money($summary['actual_expense']);?></td></tr><tr><th>Net Kâr / Zarar</th><td><strong><?php echo $this->money($summary['net_profit']);?></strong></td><th>Kâr Marjı</th><td>%<?php echo esc_html(number_format_i18n($summary['profit_margin'],2));?></td></tr><tr><th>Toplam Seyirci</th><td><?php echo esc_html(number_format_i18n($summary['total_audience']));?></td><th>Teminat Bekleyen</th><td><?php echo $this->money($summary['deposit_outstanding']);?></td></tr></tbody></table>
        <?php if(!$readiness['ready']):?><div class="notice notice-warning inline"><p><strong>Finansal kapanış henüz hazır değil:</strong></p><ul><?php foreach($readiness['blockers'] as $b):?><li><?php echo esc_html($b);?></li><?php endforeach;?></ul></div><?php elseif($summary['deposit_outstanding']>0):?><div class="notice notice-info inline"><p>Gelir-gider kapanışı hazır. Kapanış onaylandığında program <strong>Teminat İadesi Bekleniyor</strong> aşamasına geçecek.</p></div><?php else:?><div class="notice notice-success inline"><p>Gelir-gider, fatura ve teminat açısından kapanışa hazır.</p></div><?php endif;?>
        <?php if('completed'!==$program->status):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" onsubmit="return confirm('Finansal kapanış kontrolü çalıştırılsın mı? Açık kalem varsa sistem kapatmayacaktır.');"><input type="hidden" name="action" value="mmc_fin_request_close"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><?php wp_nonce_field('mmc_fin_close_'.$pid);?><button class="button button-primary button-hero">Finansal Kapanışı Değerlendir</button></form><?php else:?><div class="notice notice-success inline"><p><strong>PROGRAM FİNANSAL OLARAK KAPANDI.</strong> Teminat ve finans süreçleri tamamlandı.</p></div><?php endif;?>
        </div></div><?php
    }

    public function add_entry(){ $this->guard();$pid=absint($_POST['program_id']??0);check_admin_referer('mmc_fin_add_'.$pid);$r=MMC_Finance_Service::add_entry($pid,wp_unslash($_POST));$this->redirect($pid,$r,'Gelir/gider kaydı eklendi.'); }
    public function update_entry(){ $this->guard();$pid=absint($_POST['program_id']??0);$id=absint($_POST['entry_id']??0);check_admin_referer('mmc_fin_entry_'.$pid.'_'.$id);$r=MMC_Finance_Service::update_entry($id,wp_unslash($_POST));$this->redirect($pid,$r,'Finans kaydı güncellendi.'); }
    public function sync_invoices(){ $this->guard();$pid=absint($_POST['program_id']??0);check_admin_referer('mmc_fin_invoices_'.$pid);$r=MMC_Finance_Service::sync_invoice_queue($pid);$this->redirect($pid,$r,'Fatura kuyruğu yenilendi; yeni kayıt: '.(int)$r); }
    public function update_invoice(){ $this->guard();$pid=absint($_POST['program_id']??0);$id=absint($_POST['invoice_id']??0);check_admin_referer('mmc_fin_invoice_'.$pid.'_'.$id);$r=MMC_Finance_Service::update_invoice($id,wp_unslash($_POST));$this->redirect($pid,$r,'Fatura kaydı güncellendi.'); }
    public function generate_refund(){ $this->guard();$pid=absint($_POST['program_id']??0);$id=absint($_POST['refund_id']??0);check_admin_referer('mmc_fin_refund_letter_'.$pid.'_'.$id);$r=MMC_Finance_Service::generate_refund_letter($id);$this->redirect($pid,$r,'Teminat iade dilekçesi hazırlandı.'); }
    public function update_refund(){ $this->guard();$pid=absint($_POST['program_id']??0);$id=absint($_POST['refund_id']??0);check_admin_referer('mmc_fin_refund_'.$pid.'_'.$id);$r=MMC_Finance_Service::update_deposit_refund($id,wp_unslash($_POST));$this->redirect($pid,$r,'Teminat iade kaydı güncellendi.'); }
    public function save_close_inputs(){ $this->guard();$pid=absint($_POST['program_id']??0);check_admin_referer('mmc_fin_close_inputs_'.$pid);$r=MMC_Finance_Service::save_closure_inputs($pid,wp_unslash($_POST));$this->redirect($pid,$r,'Kapanış seyirci bilgileri kaydedildi.'); }
    public function request_close(){ $this->guard();$pid=absint($_POST['program_id']??0);check_admin_referer('mmc_fin_close_'.$pid);$r=MMC_Finance_Service::request_close($pid);$msg=is_wp_error($r)?'':('completed'===$r?'Program finansal olarak kapatıldı.':'Gelir-gider kapandı; teminat iadesi bekleniyor.');$this->redirect($pid,$r,$msg); }
    public function sync_all(){ $this->guard();$pid=absint($_POST['program_id']??0);check_admin_referer('mmc_fin_sync_'.$pid);MMC_Finance_Service::sync_external_sources($pid);$r=true;$this->redirect($pid,$r,'Finans kaynakları yenilendi.'); }
    private function redirect($pid,$result,$ok){$type=is_wp_error($result)?'error':'success';$msg=is_wp_error($result)?$result->get_error_message():$ok;wp_safe_redirect(add_query_arg(array('page'=>'mmc-finance','program_id'=>$pid,'mmc_notice'=>rawurlencode($msg),'mmc_notice_type'=>$type),admin_url('admin.php')));exit;}
    private function notice(){if(empty($_GET['mmc_notice']))return;$type=sanitize_key($_GET['mmc_notice_type']??'success');$class='error'===$type?'notice-error':'notice-success';echo '<div class="notice '.esc_attr($class).' is-dismissible"><p>'.esc_html(rawurldecode(wp_unslash($_GET['mmc_notice']))).'</p></div>';}
    private function money($v){return esc_html(number_format_i18n((float)$v,2).' TL');}
}
